import { useState } from "react";
import { useQuery, useAction } from "convex/react";
import { api } from "../convex/_generated/api";
import "./App.css";

function App() {
  const [prompt, setPrompt] = useState("");
  const [isGenerating, setIsGenerating] = useState(false);
  const [error, setError] = useState<string | null>(null);

  const generations = useQuery(api.ai.list);
  const generateAction = useAction(api.ai.generate);

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!prompt.trim()) return;

    setIsGenerating(true);
    setError(null);

    try {
      await generateAction({ prompt: prompt.trim() });
      setPrompt("");
    } catch (err: any) {
      console.error(err);
      setError(err.message || "Failed to generate AI response.");
    } finally {
      setIsGenerating(false);
    }
  };

  return (
    <div className="container">
      <header className="app-header">
        <h1>Convex AI Integration</h1>
        <p>Ask the AI anything and see the reactive updates!</p>
      </header>

      <main className="app-main">
        <section className="form-section">
          <form onSubmit={handleSubmit}>
            <div className="form-group">
              <label htmlFor="prompt">Enter a Prompt</label>
              <textarea
                id="prompt"
                value={prompt}
                onChange={(e) => setPrompt(e.target.value)}
                placeholder="Type your prompt here..."
                disabled={isGenerating}
                rows={4}
                required
              />
            </div>
            <button type="submit" className="submit-btn" disabled={isGenerating || !prompt.trim()}>
              {isGenerating ? "Generating..." : "Submit Prompt"}
            </button>
          </form>

          {error && <div className="error-message">{error}</div>}
        </section>

        <section className="results-section">
          <h2>Generated Results</h2>
          {generations === undefined ? (
            <div className="loading">Loading generations...</div>
          ) : generations.length === 0 ? (
            <div className="empty">No generations yet. Try submitting a prompt!</div>
          ) : (
            <div className="generations-list">
              {[...generations].reverse().map((gen) => (
                <div key={gen._id} className="generation-card">
                  <div className="generation-prompt">
                    <strong>Prompt:</strong> {gen.prompt}
                  </div>
                  <div className="generation-result">
                    <strong>Result:</strong>
                    <p>{gen.result}</p>
                  </div>
                  <div className="generation-time">
                    <small>Created: {new Date(gen._creationTime).toLocaleString()}</small>
                  </div>
                </div>
              ))}
            </div>
          )}
        </section>
      </main>
    </div>
  );
}

export default App;

/* Global Container styles */
.container {
  max-width: 900px;
  margin: 0 REDACTED;
  padding: 40px 20px;
  font-family: Inter, system-ui, Avenir, Helvetica, Arial, sans-serif;
  color: #f8f9fa;
  background-color: #121214;
  min-height: 100vh;
  box-sizing: border-box;
}

/* Header Styles */
.app-header {
  text-align: center;
  margin-bottom: 40px;
}

.app-header h1 {
  font-size: 2.5rem;
  margin-bottom: 10px;
  color: #38bdf8;
  font-weight: 800;
}

.app-header p {
  font-size: 1.1rem;
  color: #94a3b8;
}

/* Main Layout */
.app-main {
  display: flex;
  flex-direction: column;
  gap: 40px;
}

/* Form Styles */
.form-section {
  background-color: #1e1e24;
  padding: 24px;
  border-radius: 12px;
  box-shadow: 0 4px 6px -1px rgba(0, 0, 0, 0.1), 0 2px 4px -1px rgba(0, 0, 0, 0.06);
  border: 1px solid #2d2d34;
}

.form-group {
  display: flex;
  flex-direction: column;
  gap: 8px;
  margin-bottom: 16px;
}

.form-group label {
  font-weight: 600;
  color: #e2e8f0;
  font-size: 0.95rem;
}

textarea {
  width: 100%;
  padding: 12px;
  border-radius: 8px;
  background-color: #121214;
  border: 1px solid #3f3f46;
  color: #f4f4f5;
  font-size: 1rem;
  line-height: 1.5;
  resize: vertical;
  box-sizing: border-box;
  transition: border-color 0.2s, box-shadow 0.2s;
}

textarea:focus {
  outline: none;
  border-color: #38bdf8;
  box-shadow: 0 0 0 3px rgba(56, 189, 248, 0.2);
}

textarea:disabled {
  opacity: 0.6;
  cursor: not-allowed;
}

.submit-btn {
  background-color: #38bdf8;
  color: #0f172a;
  font-weight: 700;
  padding: 12px 24px;
  font-size: 1rem;
  border: none;
  border-radius: 8px;
  cursor: pointer;
  transition: background-color 0.2s, transform 0.1s;
  width: 100%;
}

.submit-btn:hover:not(:disabled) {
  background-color: #0ea5e9;
}

.submit-btn:active:not(:disabled) {
  transform: scale(0.98);
}

.submit-btn:disabled {
  background-color: #4b5563;
  color: #9ca3af;
  cursor: not-allowed;
}

/* Error Message */
.error-message {
  margin-top: 16px;
  background-color: rgba(239, 68, 68, 0.1);
  border: 1px solid rgba(239, 68, 68, 0.3);
  color: #f87171;
  padding: 12px;
  border-radius: 8px;
  font-size: 0.9rem;
  text-align: center;
}

/* Results Section */
.results-section h2 {
  font-size: 1.75rem;
  color: #e2e8f0;
  margin-bottom: 20px;
  border-bottom: 2px solid #2d2d34;
  padding-bottom: 10px;
}

.loading, .empty {
  text-align: center;
  padding: 40px;
  color: #94a3b8;
  font-size: 1.1rem;
  background-color: #1e1e24;
  border-radius: 12px;
  border: 1px dashed #3f3f46;
}

.generations-list {
  display: flex;
  flex-direction: column;
  gap: 20px;
}

.generation-card {
  background-color: #1e1e24;
  border-radius: 12px;
  padding: 20px;
  border: 1px solid #2d2d34;
  display: flex;
  flex-direction: column;
  gap: 12px;
  box-shadow: 0 4px 6px -1px rgba(0, 0, 0, 0.1);
}

.generation-prompt {
  background-color: #121214;
  padding: 12px;
  border-radius: 8px;
  border-left: 4px solid #38bdf8;
  color: #e2e8f0;
  font-size: 0.95rem;
}

.generation-result {
  color: #cbd5e1;
  font-size: 1rem;
  line-height: 1.6;
}

.generation-result p {
  margin: 6px 0 0 0;
  white-space: pre-wrap;
}

.generation-time {
  align-self: flex-end;
  color: #64748b;
  font-size: 0.8rem;
}

